sys_ui_action.script:
function addNewProposedPort(){
    var callingTableName = g_form.getTableName();
    var priSecondary;
    var localCircuit;
	var site;
	//alert(callingTableName);
    if (callingTableName == 'cmdb_ci_network_circuit') {
        priSecondary = g_form.getValue('x_g_sonc_ns_pro_pri_sec_circuit');
        site = g_form.getValue('x_g_sonc_ns_pro_site');
        localCircuit = g_form.getUniqueValue();
    } else if (callingTableName == 'x_g_sonc_ns_pro_nspro_tasks') {
        priSecondary = g_form.getValue('pri_sec_circuit');
        site = g_form.getValue('site');
    }


    var tableName = "x_g_sonc_ns_pro_port";

    var portSite = 'site=' + site;
    var x_g_sonc_ns_pro_pri_sec_circuit = '^x_g_sonc_ns_pro_pri_sec_circuit=' + priSecondary;
	var pendingStatus = '^pending_status=4^install_status=';


    var fullSysParmQuery = portSite + pendingStatus + x_g_sonc_ns_pro_pri_sec_circuit;


    if (localCircuit) {
        fullSysParmQuery = fullSysParmQuery + '^local_circuit_id=' + localCircuit;
    }

	//alert(fullSysParmQuery);


    var formTitle = "Add New Port";

    var gmf = new GlideModalForm(formTitle, tableName, refreshCaller);
    gmf.setPreference('sysparm_query', fullSysParmQuery);
	gmf.setPreference('sysparm_view', 'proposedports');
	gmf.setPreference('sysparm_view_forced', true);
    gmf.setSysID("-1");
    gmf.render();


    function refreshCaller() {
        location.reload();

    }


}
